import { Suspense, use, useState } from "react";
import type { Product, Review } from "./data";

type Props = { product: Product; reviews: Promise<Review[]> };

export function App({ product, reviews }: Props) {
  return (
    <html lang="en">
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <title>{`${product.name} | Trailhead`}</title>
      </head>
      <body>
        <h1>{product.name}</h1>
        <p>{formatPrice(product.priceCents)}</p>
        <p>{product.description}</p>
        <p>Updated {new Date(product.updatedAt).toLocaleDateString("en-US", { timeZone: "UTC" })}</p>
        <QuantityButton />
        <h2>Reviews</h2>
        <Suspense fallback={<p>Loading reviews…</p>}>
          <Reviews reviews={reviews} />
        </Suspense>
      </body>
    </html>
  );
}

function QuantityButton() {
  const [quantity, setQuantity] = useState(1);
  return <button onClick={() => setQuantity(quantity + 1)}>Quantity: {quantity}</button>;
}

function Reviews({ reviews }: { reviews: Promise<Review[]> }) {
  const list = use(reviews);
  if (list.length === 0) return <p>No reviews yet.</p>;
  return (
    <ul>
      {list.map((review) => (
        <li key={review.id}>
          {review.title} ({review.rating} of 5)
        </li>
      ))}
    </ul>
  );
}

function formatPrice(cents: number) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(cents / 100);
}

import type { ServerResponse } from "node:http";
import { renderToPipeableStream } from "react-dom/server";
import { App } from "./App";
import { getProduct, getReviews } from "./data";
import { dataScript } from "./dataScript";

export { getReviews };

export async function render(slug: string, res: ServerResponse, clientEntry: string) {
  const product = await getProduct(slug);
  if (!product) {
    res.writeHead(404, { "Content-Type": "text/plain" }).end("Not found");
    return;
  }
  const reviews = getReviews(slug); // not awaited: the page streams while it loads

  const { pipe } = renderToPipeableStream(<App product={product} reviews={reviews} />, {
    bootstrapScriptContent: dataScript("__PRODUCT__", product),
    bootstrapModules: [clientEntry],
    onShellReady() {
      res.writeHead(200, {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "public, s-maxage=60, stale-while-revalidate=300",
      });
      pipe(res);
    },
    onShellError() {
      res.writeHead(500, { "Content-Type": "text/plain" }).end("Something went wrong");
    },
    onError(error) {
      console.error(error);
    },
  });
}

import { createReadStream } from "node:fs";
import { readFile } from "node:fs/promises";
import http from "node:http";
import path from "node:path";
import { getReviews, render } from "./dist/server/entry-server.js";

const manifest = JSON.parse(await readFile("dist/client/.vite/manifest.json", "utf8"));
const clientEntry = "/" + manifest["src/entry-client.tsx"].file;

http
  .createServer(async (req, res) => {
    const url = new URL(req.url, "http://localhost");

    if (url.pathname.startsWith("/assets/")) {
      res.writeHead(200, {
        "Content-Type": "text/javascript",
        "Cache-Control": "public, max-age=31536000, immutable",
      });
      createReadStream(path.join("dist/client", url.pathname)).pipe(res);
      return;
    }

    const api = url.pathname.match(/^\/api\/reviews\/([a-z0-9-]+)$/);
    if (api) {
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify(await getReviews(api[1])));
      return;
    }

    const page = url.pathname.match(/^\/products\/([a-z0-9-]+)$/);
    if (page) return render(page[1], res, clientEntry);

    res.writeHead(404, { "Content-Type": "text/plain" }).end("Not found");
  })
  .listen(8080, "127.0.0.1", () => console.log("http://localhost:8080/products/storm-shell-jacket"));

import { hydrateRoot } from "react-dom/client";
import { App } from "./App";
import type { Product, Review } from "./data";

declare global {
  interface Window {
    __PRODUCT__: Product;
    __REVIEWS__?: Review[];
  }
}

const product = window.__PRODUCT__;
// A prerendered page carries its reviews. A server-rendered one fetches them.
const reviews: Promise<Review[]> = window.__REVIEWS__
  ? Promise.resolve(window.__REVIEWS__)
  : fetch(`/api/reviews/${product.slug}`).then((response) => response.json());

hydrateRoot(document, <App product={product} reviews={reviews} />);

import { prerender } from "react-dom/static";
import { App } from "./App";
import { getProduct, getReviews, listSlugs } from "./data";
import { dataScript } from "./dataScript";

export { listSlugs };

// The whole page as one HTML string, made once, at build time.
export async function prerenderPage(slug: string, clientEntry: string): Promise<string> {
  const product = await getProduct(slug);
  if (!product) throw new Error(`No product ${slug}`);
  const reviews = await getReviews(slug);

  const { prelude } = await prerender(<App product={product} reviews={Promise.resolve(reviews)} />, {
    bootstrapScriptContent: dataScript("__PRODUCT__", product) + dataScript("__REVIEWS__", reviews),
    bootstrapModules: [clientEntry],
  });
  return new Response(prelude).text();
}

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { listSlugs, prerenderPage } from "./dist/prerender/entry-prerender.js";

const manifest = JSON.parse(await readFile("dist/client/.vite/manifest.json", "utf8"));
const clientEntry = "/" + manifest["src/entry-client.tsx"].file;

for (const slug of listSlugs()) {
  const html = await prerenderPage(slug, clientEntry);
  const file = `dist/client/products/${slug}/index.html`;
  await mkdir(`dist/client/products/${slug}`, { recursive: true });
  await writeFile(file, html);
  console.log(`${file}  ${html.length} bytes`);
}

import { db } from "@/server/db";
import { formatPrice } from "@/lib/format";
import { AddToCartButton } from "./AddToCartButton";

type ProductPageProps = { params: Promise<{ slug: string }> };

export default async function ProductPage({ params }: ProductPageProps) {
  const { slug } = await params;
  const product = await db.product.findUnique({ where: { slug } });
  if (!product) return <p>We don't sell that product.</p>;

  return (
    <article>
      <h1>{product.name}</h1>
      <p>{formatPrice(product.priceCents)}</p>
      <p>{product.description}</p>
      <AddToCartButton slug={product.slug} />
    </article>
  );
}

"use client";

import { useCartStore } from "@/features/cart";

type AddToCartButtonProps = { slug: string };

export function AddToCartButton({ slug }: AddToCartButtonProps) {
